        assert!(errors.contains(&RegistryValidationError::UnsupportedVersion(2)));
    }

    #[test]
    fn registry_schema_rejects_duplicate_ids() {
        let mut text = valid_registry_toml();
        text.push_str(
            r#"
[[artifact]]
id = "example-cli"
category = "cli"
kind = "rust-binary"
source_path = "tools/example/other-cli"
owner = "tooling"
lifecycle = ["inspect"]
safety = "safe"
bin = "other"
"#,
