        let text = valid_registry_toml() + r#"
[[artifact]]
id = "example-hook"
category = "hook"
kind = "hook"
source_path = "tools/hooks/example-hook"
owner = "tooling"
lifecycle = ["enable", "disable"]
safety = "approval-required"
